css:
.sl-slider-split {
    position: relative;
    background-color: var(--smartlearn-card-bg);
    font-family: var(--smartlearn-body-font, inherit);
    overflow: hidden;
}
.sl-slider-split .carousel-inner { touch-action: pan-y; }
.sl-slider-split .sl-split-row { display: flex; flex-direction: column; min-height: 60vh; }
@media (min-width: 992px) {
    .sl-slider-split .sl-split-row {
        flex-direction: row;
        height: 70vh;
        min-height: 500px;
        max-height: 700px;
    }
}
.sl-slider-split .sl-split-content {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem 5.5rem;
    background-color: var(--smartlearn-bg);
    position: relative;
    z-index: 2;
}
.sl-slider-split .sl-split-inner { max-width: 450px; width: 100%; opacity: 0; }
.sl-slider-split .carousel-item.active .sl-split-inner {
    animation: sl-slider-split-fade 0.8s ease forwards;
}
.sl-slider-split .sl-split-badge {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, transparent);
    color: var(--smartlearn-primary);
    border-radius: 1rem;
    font-size: 0.875rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: 1.5rem;
}
.sl-slider-split .sl-split-title {
    font-family: var(--smartlearn-heading-font, inherit);
    font-size: clamp(2rem, 3.5vw, 2.75rem);
    font-weight: 800;
    color: var(--smartlearn-text);
    margin-bottom: 1rem;
    line-height: 1.2;
}
.sl-slider-split .sl-split-desc {
    font-size: 1.125rem;
    color: var(--smartlearn-text-muted);
    margin-bottom: 2rem;
    line-height: 1.6;
}
.sl-slider-split .sl-btn-split {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    padding: 0.75rem 2rem;
    font-weight: 600;
    border-radius: var(--smartlearn-radius, 0.5rem);
    transition: background-color 0.2s ease;
}
.sl-slider-split .sl-btn-split:hover,
.sl-slider-split .sl-btn-split:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-slider-split .sl-split-image {
    flex: 1;
    position: relative;
    background-color: var(--smartlearn-card-bg);
    overflow: hidden;
    min-height: 300px;
}
.sl-slider-split .sl-split-image img {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.sl-slider-split .carousel-item.active .sl-split-image img {
    animation: sl-slider-split-zoom 10s linear forwards;
}
.sl-slider-split .sl-split-controls {
    position: absolute;
    bottom: 1.5rem;
    inset-inline-start: 2rem;
    z-index: 10;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}
@media (min-width: 992px) {
    .sl-slider-split .sl-split-controls {
        inset-inline-start: max(2rem, calc((50vw - 450px) / 2));
    }
}
.sl-slider-split .sl-split-ctrl-btn {
    background: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    color: var(--smartlearn-text);
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
    box-shadow: 0 4px 6px rgba(0,0,0,0.06);
}
.sl-slider-split .sl-split-ctrl-btn:hover,
.sl-slider-split .sl-split-ctrl-btn:focus-visible {
    background: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text) !important;
    border-color: var(--smartlearn-btn-bg);
}
.sl-slider-split .sl-split-dots {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin-inline-start: 0.5rem;
}
.sl-slider-split .sl-split-dot {
    width: 24px;
    height: 24px;
    padding: 7px;
    border: none;
    background: transparent;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
}
.sl-slider-split .sl-split-dot::after {
    content: "";
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: color-mix(in srgb, var(--smartlearn-text) 30%, transparent);
    transition: background-color 0.2s ease;
}
.sl-slider-split .sl-split-dot.active::after {
    background: var(--smartlearn-primary);
}
.sl-slider-split .sl-split-ctrl-btn:focus-visible,
.sl-slider-split .sl-split-dot:focus-visible,
.sl-slider-split .sl-btn-split:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
[dir="rtl"] .sl-slider-split .sl-split-prev svg,
[dir="rtl"] .sl-slider-split .sl-split-next svg {
    transform: scaleX(-1);
}
@keyframes sl-slider-split-fade {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes sl-slider-split-zoom {
    from { transform: scale(1); }
    to { transform: scale(1.08); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-slider-split .sl-split-inner,
    .sl-slider-split .carousel-item.active .sl-split-inner {
        animation: none;
        opacity: 1;
        transform: none;
    }
    .sl-slider-split .carousel-item.active .sl-split-image img {
        animation: none;
        transform: none;
    }
    .sl-slider-split .sl-split-ctrl-btn,
    .sl-slider-split .sl-btn-split { transition: none; }
}

js:
(function() {
    function init() {
        var sections = document.querySelectorAll('.sl-slider-split');
        var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        sections.forEach(function(root) {
            if (root.dataset.slInit === '1') return;
            root.dataset.slInit = '1';

            var carousel = root.querySelector('.carousel[data-sl-ride="carousel"]');
            if (!carousel) return;

            var items = Array.prototype.slice.call(carousel.querySelectorAll('.carousel-item'));
            var indicators = Array.prototype.slice.call(carousel.querySelectorAll('[data-sl-slide-to]'));
            var prevBtns = carousel.querySelectorAll('[data-sl-slide="prev"]');
            var nextBtns = carousel.querySelectorAll('[data-sl-slide="next"]');
            var pauseBtn = carousel.querySelector('.sl-carousel-pause');
            if (items.length <= 1) return;

            var currentIndex = 0;
            items.forEach(function(item, idx) { if (item.classList.contains('active')) currentIndex = idx; });

            function syncSlideAttrs(activeIdx) {
                items.forEach(function(item, idx) {
                    var isActive = idx === activeIdx;
                    item.setAttribute('aria-hidden', isActive ? 'false' : 'true');
                    if ('inert' in item) item.inert = !isActive;
                    else if (!isActive) item.setAttribute('inert', '');
                    else item.removeAttribute('inert');
                });
                indicators.forEach(function(ind, idx) {
                    var isMatch = idx === activeIdx;
                    ind.classList.toggle('active', isMatch);
                    ind.setAttribute('aria-current', isMatch ? 'true' : 'false');
                });
            }

            items.forEach(function(item, idx) {
                item.style.transition = prefersReduced ? 'none' : 'opacity 0.6s ease-in-out';
                item.style.display = 'block';
                if (idx !== currentIndex) {
                    item.style.opacity = '0';
                    item.style.position = 'absolute';
                    item.style.inset = '0';
                    item.style.zIndex = '1';
                } else {
                    item.style.opacity = '1';
                    item.style.position = 'relative';
                    item.style.zIndex = '2';
                }
            });
            syncSlideAttrs(currentIndex);

            var isAnimating = false;
            var isPausedByUser = false;
            var autoplayTimer = null;

            function goToSlide(index) {
                if (isAnimating || index === currentIndex) return;
                var currentItem = items[currentIndex];
                var nextItem = items[index];
                if (!currentItem || !nextItem) return;

                if (prefersReduced) {
                    currentItem.classList.remove('active');
                    currentItem.style.opacity = '0';
                    currentItem.style.position = 'absolute';
                    currentItem.style.zIndex = '1';
                    nextItem.classList.add('active');
                    nextItem.style.opacity = '1';
                    nextItem.style.position = 'relative';
                    nextItem.style.zIndex = '2';
                    currentIndex = index;
                    syncSlideAttrs(currentIndex);
                    return;
                }

                isAnimating = true;
                nextItem.style.position = 'absolute';
                nextItem.style.inset = '0';
                nextItem.style.zIndex = '2';
                nextItem.style.opacity = '0';
                nextItem.classList.add('active');
                currentItem.style.zIndex = '1';
                void nextItem.offsetWidth;
                nextItem.style.opacity = '1';
                syncSlideAttrs(index);

                setTimeout(function() {
                    currentItem.classList.remove('active');
                    currentItem.style.opacity = '0';
                    nextItem.style.position = 'relative';
                    currentIndex = index;
                    isAnimating = false;
                }, 600);
            }

            function step(delta) {
                goToSlide((currentIndex + delta + items.length) % items.length);
                resetAutoplay();
            }

            function isInLiveEditor() {
                return !!root.querySelector('[data-sl-edit-id]');
            }

            function stopAutoplay() {
                if (autoplayTimer) {
                    clearInterval(autoplayTimer);
                    autoplayTimer = null;
                }
            }

            function startAutoplay() {
                stopAutoplay();
                if (isPausedByUser || prefersReduced || document.hidden || isInLiveEditor()) return;
                autoplayTimer = setInterval(function() {
                    goToSlide((currentIndex + 1) % items.length);
                }, 5000);
            }

            function resetAutoplay() {
                if (!isPausedByUser) startAutoplay();
            }

            prevBtns.forEach(function(btn) { btn.addEventListener('click', function(e) { e.preventDefault(); step(-1); }); });
            nextBtns.forEach(function(btn) { btn.addEventListener('click', function(e) { e.preventDefault(); step(1); }); });
            indicators.forEach(function(ind) {
                ind.addEventListener('click', function(e) {
                    e.preventDefault();
                    var target = parseInt(ind.getAttribute('data-sl-slide-to'), 10);
                    if (!isNaN(target)) { goToSlide(target); resetAutoplay(); }
                });
            });

            if (pauseBtn) {
                var iconPause = pauseBtn.querySelector('.sl-icon-pause');
                var iconPlay = pauseBtn.querySelector('.sl-icon-play');
                pauseBtn.addEventListener('click', function() {
                    isPausedByUser = !isPausedByUser;
                    pauseBtn.setAttribute('aria-pressed', isPausedByUser ? 'true' : 'false');
                    pauseBtn.setAttribute('aria-label', isPausedByUser ? 'Play autoplay' : 'Pause autoplay');
                    if (iconPause) iconPause.style.display = isPausedByUser ? 'none' : '';
                    if (iconPlay) iconPlay.style.display = isPausedByUser ? '' : 'none';
                    if (isPausedByUser) stopAutoplay(); else startAutoplay();
                });
            }

            root.addEventListener('keydown', function(e) {
                var rtl = window.getComputedStyle(root).direction === 'rtl';
                if (e.key === 'ArrowLeft') { e.preventDefault(); step(rtl ? 1 : -1); }
                else if (e.key === 'ArrowRight') { e.preventDefault(); step(rtl ? -1 : 1); }
            });

            var startX = 0;
            var inner = carousel.querySelector('.carousel-inner');
            if (inner) {
                inner.addEventListener('pointerdown', function(e) { startX = e.clientX; });
                inner.addEventListener('pointerup', function(e) {
                    var dx = e.clientX - startX;
                    if (Math.abs(dx) < 40) return;
                    var rtl = window.getComputedStyle(root).direction === 'rtl';
                    step((dx < 0 ? 1 : -1) * (rtl ? -1 : 1));
                });
            }

            carousel.addEventListener('mouseenter', stopAutoplay);
            carousel.addEventListener('mouseleave', startAutoplay);
            carousel.addEventListener('focusin', stopAutoplay);
            carousel.addEventListener('focusout', function() {
                setTimeout(function() { if (!carousel.contains(document.activeElement)) startAutoplay(); }, 0);
            });
            document.addEventListener('visibilitychange', function() {
                if (document.hidden) stopAutoplay(); else startAutoplay();
            });

            startAutoplay();
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
